/**
 * Omits the key-value pairs corresponding to the given keys from an object.
 *
 * @param {*} obj
 * @param {any[]} arr
 */
const omit = (obj, arr) => Object.keys(obj)
    .filter((k) => !arr.includes(k))
    .reduce((acc, key) => ((acc[key] = obj[key]), acc), {});
export default omit;
